  "client:https://ds.canonical.com/apps_lxd.component.meter:values:7": {
    __id: "client:https://ds.canonical.com/apps_lxd.component.meter:values:7",
    __typename: "NodeValue",
    field: "anatomyDsl",
    label: "anatomyDsl",
    type: "text",
    text: 'node:\n  uri: core:component:Meter\n  styles:\n    # Structural (implicitly invariant)\n    layout.type: stack\n    layout.direction: vertical\n    layout.align: start\n    \n    # Themeable\n    spacing.gap: spacing/small\n    \n  edges:\n    - node:\n        role: meter bar container\n        styles:\n          # Structural (implicitly invariant)\n          layout.type: flow\n          layout.direction: horizontal\n          layout.align: start\n          size.width: fill\n          size.height: hug\n          \n          # Themeable\n          appearance.background: color/background/meter\n          appearance.radius: shape/rounded/small\n          size.min.height: size/meter/height\n          \n        edges:\n          - node:\n              role: primary meter bar\n              styles:\n                # Structural (implicitly invariant)\n                layout.display: block\n                size.height: fill\n                \n                # Dynamic width based on percentage prop\n                # Note: actual width calculation happens at runtime\n                size.min.width: size/meter/minimum\n                \n                # Themeable\n                appearance.background: color/meter/primary\n                appearance.radius: shape/rounded/small\n                \n            relation:\n              cardinality: "1..1"\n              \n          - node:\n              role: secondary meter bar\n              styles:\n                # Structural (implicitly invariant)\n                layout.display: block\n                size.height: fill\n                \n                # Themeable\n                appearance.background: color/meter/secondary\n                appearance.radius: shape/rounded/small\n                \n            relation:\n              cardinality: "0..1"\n              \n      relation:\n        cardinality: "1..1"\n        slotName: meter\n        \n    - node:\n        role: description text\n        styles:\n          # Structural (implicitly invariant)\n          layout.display: block\n          \n          # Themeable\n          typography.size: font/size/small\n          typography.color: color/text/muted\n          spacing.margin.top: spacing/none\n          spacing.margin.bottom: spacing/none\n          \n      relation:\n        cardinality: "1..1"\n        slotName: description',
    uri: null,
  },
